/// <summary>
/// Logic block used to move license plates
/// </summary>
class MwmsLogicBlockMoveLicensePlate extends TFMLogicBlock implements TFMLogicBlockDataCollectionInterface
{
    InventJournalTable  inventJournalTable;
}

Method.Source:
public static MwmsLogicBlockMoveLicensePlate Construct()
{
    return new MwmsLogicBlockMoveLicensePlate();
}

protected void new()
{
    super();
    categories.add("@SYS6437");
    categories.add("@WAX67");
}

public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    TFMRegistrationCollectorList    fromWarehouse = TFMGetReferenceData::createDefaultWarehouseReferenceData(1, strLwr(extendedTypeStr(InventLocationId)), "@SYS25253", methodStr(TFMGetReferenceData,WarehouseList));
    TFMRegistrationCollectorText    lpField;
    // Warehouse to move from
    fromWarehouse.parmLinkedElement(2);
    fromWarehouse.parmLinkColumn(extendedTypeStr(InventLocationId));
    refConf.addCollector(fromWarehouse);
    // Warehouse to move to
    refConf.addCollector(TFMGetReferenceData::createDefaultWarehouseReferenceData(2,'To'+ strLwr(extendedTypeStr(InventLocationId)), "@SYS8519", methodStr(TFMGetReferenceData,WarehouseList)));
    // LP text box
    lpField = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WHSLicensePlateId));
    lpField.parmOptional(false);
    refConf.addCollector(lpField);

    return refConf;
}

/// <summary>
/// This method gives you the registration collectors for this data collection block.
/// </summary>
/// <returns>A collection of registration collectors.</returns>
public TFMRegistrationCollectors registrationCollectors()
{
    TFMRegistrationCollectors   regCols = components.getCollectors();
    TFMRegistrationCollector    regCol  = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WMSLocationId),'To' + extendedTypeStr(WMSLocationId),"@TFM:MEL44","@SYS50351","@TFM:MEL45");
    regCols.addCollector(regCol);        
    return regCols;
}

public TFMPostResponseData post()
{
    TFMPostResponseData response        = TFMPostResponseData::Construct();
    wmsLocationid       WMSLocId        = request.getFieldValue('To' + extendedTypeStr(WMSLocationId));
    WHSLicensePlateId   lp              = request.getFieldValue(extendedTypeStr(WHSLicensePlateId));
    InventLocationId    warehouse       = request.getFieldValue('To'+ strLwr(extendedTypeStr(InventLocationId)));

    inventJournalTable = MobPostHelper::MoveLicensePlate(lp,warehouse,wmslocid);

    response.parmResponseText(SysLabel::labelId2String2("@TFM:MEL47"));
    return response;
}
